.dc-popover__wrapper {
  position: relative;
}
.dc-popover__container {
  position: absolute;
  /* rtl:ignore */
  left: 0;
  top: 0;
  width: 280px;
}
.dc-popover__container-relative {
  position: relative;
}
.dc-popover__target__icon .counter {
  color: var(--brand-red-coral);
  font-size: 10px;
  font-weight: bold;
  line-height: 1.4em;
  position: absolute;
  top: 50%;
  transform: translateY(-65%);
}
.dc-popover__bubble {
  font-size: 1.2rem;
  color: var(--text-colored-background);
  font-weight: 400;
  text-transform: none;
  text-align: center;
  line-height: 1.25;
  cursor: help;
  position: relative;
  padding: 0.8rem;
  max-width: 31.7rem;
  border-radius: 4px;
  display: flex;
  flex-direction: row;
  background: var(--general-active);
  color: var(--text-prominent);
  z-index: 1;
  align-items: center;
}
.dc-popover__bubble__icon {
  flex-grow: 1;
  margin-right: 0.7em;
  padding-top: 3px;
}
.dc-popover__bubble__text {
  flex-grow: 2;
  direction: ltr;
}
.dc-popover__bubble--error {
  direction: ltr;
  background-color: var(--status-danger);
}
@media (max-width: 1279px) {
  .dc-popover__trade-params {
    max-width: calc(100vw - 6.7rem);
  }
}

.mobile-widget__item-popover,
.accu-info-display__popover {
  max-width: 28rem;
}

@media (max-width: 1279px) {
  .accu-info-display__popover {
    max-width: 33rem;
    margin-right: 1rem;
  }
