.journal-stats-modal-body {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 10px 16px 16px;
}
@media (max-width: 1279px) {
  .journal-stats-modal-body {
    padding: 10px 6px;
  }
}
.journal-stats-modal-body__text {
  margin-bottom: 8px;
  color: var(--text-general);
  width: 100%;
}
.journal-stats-modal-body__video {
  margin-bottom: 16px;
  border-radius: 4px;
  overflow: hidden;
  width: 56.3rem;
  height: 44.8rem;
}
@media (max-width: 1279px) {
  .journal-stats-modal-body__video {
    width: 100%;
    height: 320px;
  }
}
.journal-stats-modal-body__video iframe {
  width: 100%;
  height: 100%;
  border: 0;
}
.journal-stats-modal-body__video video {
  transform: scale(1);
}
.journal-stats-modal-body__video .stream__wrapper {
  width: 100%;
  height: 100%;
}

.stream__wrapper {
  position: relative;
  width: 100%;
  height: 100%;
}
.stream__wrapper--is-loading {
  background-color: var(--color-surface);
}

.stream__loading-skeleton {
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, var(--color-surface) 25%, var(--color-surface-light) 50%, var(--color-surface) 75%);
  background-size: 200% 100%;
  animation: loading 1.5s infinite;
  position: absolute;
  top: 0;
  inset-inline-start: 0;
  z-index: 1;
}

@keyframes loading {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}
@keyframes loading {
  0% {
    background-position: -200% 0;
  }
  100% {
    background-position: 200% 0;
  }
}

.info-icon {
  cursor: pointer;
  margin-inline-start: 5px;
  vertical-align: sub;
  height: 14px;
  width: 14px;
}
.info-icon:hover {
  opacity: 0.7;
  transition: all 0.2s ease;
}.download__container {
  display: flex;
  padding: 12px;
  padding-left: 16px;
  border: solid 1px var(--general-section-1);
}
.download__container__view-detail-button {
  height: 3.2rem;
}

.run-panel__info .download__button {
  height: 3.2rem;
