@keyframes journal-signal-in {
  0% {
    opacity: 0;
    transform: translateY(-6px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes move-in {
  0% {
    transform: translateX(300px);
    opacity: 0;
  }
  100% {
    transform: translateX(0);
    opacity: 1;
  }
}
.journal .ReactVirtualized__Grid__innerScrollContainer > :first-child,
.journal .ReactVirtualized__Grid__innerScrollContainer :before,
.journal .ReactVirtualized__Grid__innerScrollContainer :after {
  box-sizing: border-box;
  animation: move-in 0.4s ease-in forwards;
}
.journal-empty {
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.journal-empty svg g path {
  fill: var(--text-less-prominent);
}
.journal-empty__header {
  padding: 0.8rem;
}
.journal-empty__icon {
  align-self: center;
}
.journal-empty__message {
  margin: 0 auto;
}
.journal-empty__message .dc-text {
  line-height: var(--text-lh-xxl);
}
.journal-empty__list {
  list-style-type: disc;
  margin-left: 20px;
  line-height: var(--text-lh-xl);
}
.journal-empty__list li::marker {
  color: var(--text-less-prominent);
}
.journal__item {
  padding: 16px;
}
.journal__item-list {
  height: calc(100% - 7.2rem);
}
.journal__item-content > * {
