  background: var(--status-warning) !important;
}
.dc-progress-slider__line--red {
  background: var(--status-danger) !important;
}
.dc-progress-slider__infinite-loader {
  position: relative;
  height: 4px;
  display: block;
  width: 100%;
  background-color: var(--state-hover);
