.animation__progress .circular-wrapper {
  width: 2px;
  height: 2px;
  align-self: center;
  display: flex;
}
.animation__progress .circular-wrapper .static-circle {
  width: 2px;
  height: 2px;
  background-color: #000;
  border-radius: 100%;
  align-self: center;
  z-index: 1;
}
.animation__progress .circular-wrapper .dynamic-circle {
  border-radius: 100%;
  height: 10px;
  width: 10px;
  margin-left: -4px;
  margin-top: -4px;
  opacity: 0.32;
  position: absolute;
}
.animation__progress .circular-wrapper:nth-child(2) {
  margin-left: 3px;
