  border: 2px solid rgba(0, 255, 100, 0.4);
  border-radius: 16px;
  padding: 24px;
  width: 360px;
  max-width: calc(100vw - 40px);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.8), 0 0 40px rgba(0, 255, 100, 0.1);
  animation: popup-in 0.3s cubic-bezier(0.34, 1.2, 0.64, 1);
}
.ai-scanner__ahmed-popup-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}
.ai-scanner__ahmed-popup-header span {
  font-size: 15px;
  font-weight: 700;
  color: #00ff88;
}
.ai-scanner__ahmed-popup-header button {
  background: none;
  border: none;
  color: #64748b;
  cursor: pointer;
  font-size: 16px;
}
.ai-scanner__ahmed-popup-header button:hover {
  color: #f87171;
}
.ai-scanner__ahmed-popup-body p {
  font-size: 13px;
  color: #86efac;
  margin: 0 0 8px;
}
.ai-scanner__ahmed-popup-body strong {
  color: #00ff88;
}
.ai-scanner__ahmed-bot-name {
  margin-top: 12px !important;
  font-size: 14px !important;
  font-weight: 700 !important;
  color: #00ff88 !important;
  padding: 10px;
  background: rgba(0, 255, 100, 0.06);
  border-radius: 8px;
  border: 1px solid rgba(0, 255, 100, 0.15);
}
.ai-scanner__ahmed-bot-settings {
  font-size: 11px !important;
  color: rgba(134, 239, 172, 0.6) !important;
  margin-top: 6px !important;
}
.ai-scanner__ahmed-popup-actions {
  display: flex;
  gap: 10px;
  margin-top: 20px;
}
.ai-scanner__ahmed-load-btn {
  flex: 1;
  padding: 12px;
  border-radius: 10px;
  background: linear-gradient(135deg, #00c853, #00e676);
  color: #000;
  border: none;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.18s;
  box-shadow: 0 4px 15px rgba(0, 200, 83, 0.4);
}
.ai-scanner__ahmed-load-btn:hover {
  filter: brightness(1.1);
  transform: translateY(-1px);
}
.ai-scanner__ahmed-dismiss-btn {
  padding: 12px 16px;
  border-radius: 10px;
  border: 1.5px solid rgba(255, 255, 255, 0.1);
  background: transparent;
  color: #64748b;
  font-size: 13px;
  cursor: pointer;
}
.ai-scanner__ahmed-dismiss-btn:hover {
  border-color: rgba(255, 255, 255, 0.2);
  color: #94a3b8;
}

@keyframes orbPulse {
  0%, 100% {
    box-shadow: 0 0 18px rgba(0, 255, 100, 0.35), 0 4px 24px rgba(0, 0, 0, 0.7), inset 0 0 12px rgba(0, 255, 100, 0.08);
  }
  50% {
    box-shadow: 0 0 30px rgba(0, 255, 100, 0.6), 0 4px 24px rgba(0, 0, 0, 0.7), inset 0 0 18px rgba(0, 255, 100, 0.15);
  }
}
@keyframes badgeBounce {
  from {
    transform: scale(0);
  }
  to {
    transform: scale(1);
  }
}
@keyframes panelSlideIn {
  from {
    opacity: 0;
    transform: scale(0.88) translateY(12px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes scanner-pulse {
  0%, 100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.3;
    transform: scale(0.7);
  }
}
@keyframes signal-in {
  from {
    opacity: 0;
    transform: translateX(-8px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes badge-pulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}
@keyframes ahmed-glow {
  0%, 100% {
    box-shadow: 0 0 6px rgba(0, 200, 83, 0.5);
  }
  50% {
    box-shadow: 0 0 12px rgba(0, 200, 83, 0.9);
  }
}
@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes popup-in {
  from {
    opacity: 0;
    transform: scale(0.9) translateY(20px);
  }
  to {
    opacity: 1;
    transform: none;
  }
