}.chart-ai {
  margin: 4px 10px 6px;
  width: calc(100% - 20px);
  max-width: 100%;
  min-width: 0;
  box-sizing: border-box;
  border: 1px solid #dbe4ef;
  border-radius: 10px;
  background: linear-gradient(135deg, #f8fbff, #eef5ff);
  color: #152238;
  font-family: Inter, Poppins, sans-serif;
  font-size: 10px;
  overflow: visible;
  position: relative;
  z-index: 4;
}

.chart-ai--active {
  border-color: #1e88ff;
  box-shadow: 0 0 0 2px rgba(30, 136, 255, 0.1);
}

.chart-ai__body {
  max-height: min(66vh, 520px);
  min-width: 0;
  width: 100%;
  overflow-x: hidden;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(30, 136, 255, 0.55) rgba(30, 136, 255, 0.08);
  overscroll-behavior: contain;
}
.chart-ai__body::-webkit-scrollbar {
  width: 7px;
  height: 7px;
}
.chart-ai__body::-webkit-scrollbar-track {
  background: rgba(30, 136, 255, 0.08);
  border-radius: 8px;
}
.chart-ai__body::-webkit-scrollbar-thumb {
  background: rgba(30, 136, 255, 0.45);
  border-radius: 8px;
}
.chart-ai__body::-webkit-scrollbar-thumb:hover {
  background: rgba(30, 136, 255, 0.7);
}

.chart-ai__head {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 7px;
  min-width: 0;
}

.chart-ai__power {
  border: 0;
  border-radius: 7px;
  padding: 5px 8px;
  background: #172033;
  color: #fff;
  font-weight: 900;
  font-size: 10px;
  cursor: pointer;
}

.chart-ai__power.on {
  background: linear-gradient(135deg, #1769ff, #00b86b);
}

.chart-ai__power:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.chart-ai__title {
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  font-weight: 900;
  white-space: nowrap;
}

.chart-ai__status {
  min-width: 0;
  flex: 1 1 auto;
  color: #637083;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.chart-ai__scan {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 4px 8px;
  border-top: 1px solid #dbe4ef;
  color: #285d9f;
  font-weight: 800;
}

.chart-ai__scan span {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  display: inline-block;
  background: #1e88ff;
}

.chart-ai__scan .pulse {
  animation: chart-ai-pulse 1s infinite;
}

.chart-ai__scan .ready {
  background: #00a550;
}

@keyframes chart-ai-pulse {
  50% {
    opacity: 0.25;
    transform: scale(0.7);
  }
}
.chart-ai__toggles {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3px;
  padding: 5px 7px;
}

.chart-ai__toggles button, .chart-ai__sides button {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  border: 1px solid #d5dfeb;
  border-radius: 6px;
  padding: 4px 3px;
  background: #fff;
  color: #64748b;
  font-size: 9px;
  font-weight: 800;
  cursor: pointer;
}

.chart-ai__toggles button.active, .chart-ai__sides button.active {
  border-color: #1684ff;
  background: #e4f1ff;
  color: #0755a1;
}

.chart-ai__mode-picker {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3px;
  padding: 0 7px 5px;
}
.chart-ai__mode-picker .chart-ai__strategy-label {
  grid-column: 1/-1;
}
.chart-ai__mode-picker button, .chart-ai__mode-picker .chart-ai__mode-fixed {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  border: 1px solid #d5dfeb;
  border-radius: 6px;
  padding: 5px 4px;
  background: #fff;
  color: #64748b;
  font-size: 9px;
  font-weight: 800;
  cursor: pointer;
}
.chart-ai__mode-picker button.active, .chart-ai__mode-picker .chart-ai__mode-fixed.active {
  border-color: #1684ff;
  background: #e4f1ff;
  color: #0755a1;
}
.chart-ai__mode-picker .chart-ai__mode-fixed {
  grid-column: 1/-1;
  border-color: #1684ff;
  background: #e4f1ff;
  color: #0755a1;
  text-align: center;
  cursor: default;
}

.chart-ai__settings {
