}

.chart-ai__settings--controls .chart-ai__stake-field {
  width: 42px;
}

.chart-ai__settings--risk {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: center;
  gap: 4px 6px;
}

.chart-ai__settings--risk label {
  justify-content: space-between;
}

.chart-ai__auto-value {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 31px;
  min-height: 21px;
  padding: 2px 5px;
