  border-radius: 4px;
  background: #e4f1ff;
  color: #0755a1;
  font-size: 9px;
  font-weight: 900;
}

.chart-ai__stake-readout {
  margin-left: auto;
  color: #0755a1;
  font-weight: 900;
  white-space: nowrap;
}

.chart-ai__sides {
  display: flex;
  gap: 4px;
  align-items: center;
  flex-wrap: wrap;
  padding: 0 7px 6px;
  min-width: 0;
}

.chart-ai__sides span {
  flex: 1 1 100%;
  min-width: 0;
  margin-left: 0;
  color: #64748b;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.chart-ai__entry {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 5px 7px 2px;
  color: #285d9f;
  line-height: 1.3;
}

.chart-ai__entry b {
  color: #152238;
  font-size: 10px;
}

.chart-ai__cycle-route {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 0 7px 5px;
  padding: 5px 7px;
  border: 1px solid #9bd7c3;
  border-radius: 6px;
  background: linear-gradient(135deg, #effff7, #e8f4ff);
  color: #17634e;
  line-height: 1.3;
}

.chart-ai__cycle-route strong {
  color: #0755a1;
  font-size: 10px;
}

.chart-ai__cycle-route span {
  font-weight: 900;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.chart-ai__cycle-route small {
  color: #637083;
  font-size: 9px;
}

.chart-ai__entry span {
  color: #637083;
}

.chart-ai__entry-map {
  color: #285d9f !important;
  font-weight: 800;
  overflow-wrap: anywhere;
}

.chart-ai__flow {
  color: #0f766e !important;
  font-weight: 800;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.chart-ai__circle-readout {
  overflow-wrap: anywhere;
  font-size: 9px;
}

.chart-ai__strategy-picker {
  position: relative;
  margin: 0 7px 5px;
  min-width: 0;
  width: calc(100% - 14px);
}

.chart-ai__strategy-label {
  display: block;
  padding: 0 0 2px;
  color: #64748b;
  font-weight: 800;
}

.chart-ai__strategy-trigger {
  width: 100%;
  min-height: 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
