}
.chart-ai__strategy-trigger span:first-child {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.chart-ai__strategy-trigger.open {
  border-color: #1684ff;
  box-shadow: 0 0 0 2px rgba(30, 136, 255, 0.1);
}

.chart-ai__strategy-menu {
  position: absolute;
  left: 0;
  right: 0;
