  overflow-y: auto;
  padding: 3px;
  border: 1px solid #c8d7e8;
  border-radius: 6px;
  background: #fff;
  box-shadow: 0 8px 18px rgba(15, 35, 65, 0.18);
  scrollbar-width: thin;
}

.chart-ai__strategy-option {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 6px;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: #24344d;
  font-size: 9px;
  text-align: left;
  cursor: pointer;
}
.chart-ai__strategy-option:hover, .chart-ai__strategy-option.selected {
  background: #eaf4ff;
  color: #0755a1;
}

.chart-ai__strategy-check {
  width: 11px;
  color: #1684ff;
  font-weight: 900;
}

.chart-ai__popup {
