  color: #00a550;
  border: 1px solid rgba(0, 200, 83, 0.2);
}
.ctp__result.err {
  background: rgba(255, 61, 87, 0.08);
  color: #e02020;
  border: 1px solid rgba(255, 61, 87, 0.2);
}

/* ── Accumulator running notice ─────────────────────────────────────────────── */
.ctp__accu-running {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 6px;
  padding: 4px 8px;
  background: rgba(0, 200, 83, 0.08);
  border: 1px solid rgba(0, 200, 83, 0.25);
  border-radius: 6px;
