  margin-bottom: 6px;
}
.ctp__accu-stats-grid > div {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  padding: 4px 5px;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.75);
}
.ctp__accu-stats-grid span {
  color: #8492a6;
  font-size: 9px;
  font-weight: 700;
}
.ctp__accu-stats-grid strong {
  overflow: hidden;
  color: #172033;
  font-size: 11px;
  font-weight: 900;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ctp__accu-stats-grid strong.is-positive {
  color: #079455;
}
.ctp__accu-stats-grid strong.is-negative {
  color: #d9363e;
}

.ctp__accu-value-row {
  padding-top: 5px;
  border-top: 1px solid rgba(142, 177, 212, 0.35);
}
.ctp__accu-value-row strong {
  color: #172033;
  font-size: 11px;
  font-weight: 900;
}

/* ── Accumulator Take Profit section ───────────────────────────────────────── */
.ctp__accu-tp-section {
  padding: 0 10px;
  margin-bottom: 5px;
}

.ctp__accu-tp-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 6px;
}

.ctp__accu-tp-label {
  display: flex;
  align-items: center;
  gap: 7px;
