}

.ctp__accu-tp-ctrl {
  margin-bottom: 6px;
}

/* ── Accumulator max payout / ticks info ────────────────────────────────────── */
.ctp__accu-info {
  border-top: 1px solid #f0f0f0;
  padding-top: 6px;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.ctp__accu-info-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 11px;
}

.ctp__accu-info-key {
  color: #6b7280;
  font-weight: 500;
}

.ctp__accu-info-val {
  font-weight: 800;
  color: #0E0F11;
  font-variant-numeric: tabular-nums;
}

/* ── Over / Under buttons ───────────────────────────────────────────────────── */
.ctp__section--over,
.ctp__section--under {
  margin-bottom: 0;
}

.ctp__buy-btn {
  width: 100%;
  min-height: 44px;
  border-radius: 14px;
  border: none;
