}
.ctp__buy-btn--over {
  background: linear-gradient(120deg, #00C853 0%, #00E676 100%);
  box-shadow: 0 2px 8px rgba(0, 200, 83, 0.3);
}
.ctp__buy-btn--over:hover:not(:disabled) {
  filter: brightness(1.06);
  box-shadow: 0 4px 14px rgba(0, 230, 118, 0.45);
}
.ctp__buy-btn--under {
  background: linear-gradient(120deg, #FF3D57 0%, #C62828 100%);
  box-shadow: 0 2px 8px rgba(255, 61, 87, 0.3);
}
.ctp__buy-btn--under:hover:not(:disabled) {
  filter: brightness(1.06);
  box-shadow: 0 4px 14px rgba(255, 61, 87, 0.45);
}
.ctp__buy-btn--accu-sell {
