.wa-float-panel__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #22c55e;
  box-shadow: 0 0 6px #22c55e;
  animation: wa-dot-blink 1.2s ease-in-out infinite;
}

.wa-float-panel__hdr-right {
  display: flex;
  align-items: center;
  gap: 5px;
}

.wa-float-panel__cd {
  font-size: 0.65rem;
  color: rgba(255, 255, 255, 0.35);
  font-variant-numeric: tabular-nums;
}

.wa-float-panel__min,
.wa-float-panel__close {
  background: none;
  border: none;
  color: rgba(255, 255, 255, 0.45);
  font-size: 0.72rem;
  cursor: pointer;
  padding: 2px 5px;
  border-radius: 4px;
  line-height: 1;
}
.wa-float-panel__min:hover,
.wa-float-panel__close:hover {
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
}

.wa-float-panel__close {
  color: rgba(239, 68, 68, 0.7);
}
.wa-float-panel__close:hover {
  background: rgba(239, 68, 68, 0.15);
  color: #ef4444;
}

/* tabs */
.wa-float-tabs {
  display: flex;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.wa-float-tabs__btn {
  flex: 1;
  padding: 6px 8px;
  background: none;
  border: none;
  color: rgba(255, 255, 255, 0.4);
  font-size: 0.71rem;
  font-weight: 600;
  cursor: pointer;
  transition: color 0.15s, background 0.15s;
  letter-spacing: 0.02em;
}
.wa-float-tabs__btn:hover {
  color: rgba(255, 255, 255, 0.7);
  background: rgba(255, 255, 255, 0.04);
}
.wa-float-tabs__btn.active {
  color: #25D366;
  background: rgba(37, 211, 102, 0.08);
  border-bottom: 2px solid #25D366;
}

/* body */
.wa-float-body {
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 510px;
  overflow-y: auto;
  cursor: default;
}

/* signal card */
.wa-float-card {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(37, 211, 102, 0.18);
  border-radius: 10px;
  padding: 9px 11px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.wa-float-card__top {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 3px;
}

.wa-float-card__market {
  background: rgba(99, 102, 241, 0.25);
  color: #a5b4fc;
  font-size: 0.7rem;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 20px;
}

.wa-float-card__action {
  font-size: 0.76rem;
  font-weight: 800;
  color: #f0f4ff;
  letter-spacing: 0.04em;
  flex: 1;
}

.wa-float-card__conf {
  font-size: 0.78rem;
  font-weight: 800;
}

.wa-float-card__live-badge {
  background: rgba(37, 211, 102, 0.2);
  color: #22c55e;
  font-size: 0.6rem;
  font-weight: 800;
  padding: 1px 5px;
  border-radius: 4px;
  letter-spacing: 0.06em;
}

.wa-float-row {
  display: flex;
  align-items: flex-start;
  gap: 5px;
}

.wa-float-lbl {
  font-size: 0.67rem;
  color: rgba(255, 255, 255, 0.38);
  min-width: 75px;
  flex-shrink: 0;
}

.wa-float-val {
  font-size: 0.71rem;
  color: #e2e8f0;
  font-weight: 600;
}
.wa-float-val.bot {
  color: #fbbf24;
  font-style: italic;
}
.wa-float-val.dim {
  color: rgba(255, 255, 255, 0.45);
  font-size: 0.65rem;
}

/* share button on card */
.wa-float-share-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  margin-top: 4px;
  padding: 5px 10px;
  border-radius: 7px;
  border: none;
  background: #25D366;
  color: #000;
  font-size: 0.68rem;
  font-weight: 800;
  cursor: pointer;
  transition: opacity 0.15s;
}
.wa-float-share-btn:hover {
  opacity: 0.85;
}

/* history */
.wa-float-history {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.wa-float-hist-row {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 0.64rem;
  color: rgba(255, 255, 255, 0.4);
  padding: 3px 6px;
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.02);
  border: 1px solid rgba(255, 255, 255, 0.04);
}

.wa-float-hist-mkt {
  color: #818cf8;
  font-weight: 700;
  min-width: 32px;
}

.wa-float-hist-act {
  flex: 1;
}

.wa-float-hist-conf {
  color: #86efac;
  font-weight: 700;
}

.wa-float-hist-time {
  color: rgba(255, 255, 255, 0.28);
}

.wa-float-hist-live {
  background: rgba(37, 211, 102, 0.18);
  color: #22c55e;
  font-size: 0.55rem;
  padding: 1px 4px;
  border-radius: 3px;
  font-weight: 800;
}

.wa-float-hist-share {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 0.7rem;
  padding: 0 2px;
  opacity: 0.5;
}
.wa-float-hist-share:hover {
  opacity: 1;
}

/* links */
.wa-float-links {
  display: flex;
  gap: 7px;
}

.wa-float-link {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 6px 8px;
  border-radius: 8px;
  font-size: 0.71rem;
  font-weight: 700;
  text-decoration: none;
  transition: opacity 0.15s;
}
.wa-float-link:hover {
  opacity: 0.85;
}
.wa-float-link.green {
  background: #25D366;
  color: #000;
}
.wa-float-link.blue {
  background: rgba(99, 102, 241, 0.22);
  color: #a5b4fc;
  border: 1px solid rgba(99, 102, 241, 0.28);
}

.wa-float-note {
  font-size: 0.6rem;
  color: rgba(255, 255, 255, 0.22);
  margin: 0;
  text-align: center;
}

/* ─── copy btn ─── */
.wa-copy-btn {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 5px;
  padding: 3px 8px;
  font-size: 0.65rem;
  color: #e2e8f0;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.15s;
}
.wa-copy-btn:hover {
  background: rgba(255, 255, 255, 0.16);
}

/* ─── step dots ─── */
.wa-step-dots {
  display: flex;
  gap: 5px;
  align-items: center;
}

.wa-step-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.15);
  border: 1px solid rgba(255, 255, 255, 0.2);
  transition: all 0.2s;
}
.wa-step-dot.active {
  background: #25D366;
  border-color: #25D366;
  box-shadow: 0 0 6px #25D366;
}
.wa-step-dot.done {
  background: rgba(37, 211, 102, 0.4);
  border-color: rgba(37, 211, 102, 0.5);
}

/* ─── Pair tab ─── */
.wa-float-pair {
  gap: 10px;
}
.wa-float-pair .wa-pair-step-header {
  display: flex;
  align-items: center;
  gap: 8px;
}
.wa-float-pair .wa-pair-step-label {
  font-size: 0.64rem;
  color: rgba(255, 255, 255, 0.38);
}
.wa-float-pair {
  /* hero */
}
.wa-float-pair .wa-pair-hero {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  padding: 6px 0;
  text-align: center;
}
.wa-float-pair .wa-pair-hero-title {
  font-size: 0.92rem;
  font-weight: 800;
  color: #e2e8f0;
  margin: 0;
}
.wa-float-pair .wa-pair-hero-sub {
  font-size: 0.67rem;
  color: rgba(255, 255, 255, 0.45);
  margin: 0;
}
.wa-float-pair {
  /* field */
}
.wa-float-pair__field {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.wa-float-pair__field label {
  font-size: 0.68rem;
  color: rgba(255, 255, 255, 0.5);
}
.wa-float-pair__field input {
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  padding: 8px 10px;
  color: #e2e8f0;
  font-size: 0.78rem;
  outline: none;
  transition: border-color 0.15s;
  width: 100%;
  box-sizing: border-box;
}
.wa-float-pair__field input:focus {
  border-color: rgba(37, 211, 102, 0.55);
}
.wa-float-pair__field input::placeholder {
  color: rgba(255, 255, 255, 0.22);
}
.wa-float-pair .wa-pair-field-error {
  font-size: 0.65rem;
  color: #f87171;
}
.wa-float-pair {
  /* code card */
}
.wa-float-pair .wa-pair-code-card {
  background: rgba(37, 211, 102, 0.07);
  border: 1px solid rgba(37, 211, 102, 0.25);
  border-radius: 10px;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.wa-float-pair .wa-pair-code-label {
  font-size: 0.68rem;
  color: #86efac;
  margin: 0;
  font-weight: 700;
}
.wa-float-pair .wa-pair-code-value {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  background: rgba(0, 0, 0, 0.3);
  border-radius: 7px;
  padding: 7px 10px;
}
.wa-float-pair .wa-pair-code-value span {
  font-size: 1.15rem;
  font-weight: 900;
  color: #fbbf24;
  letter-spacing: 0.12em;
  font-family: monospace;
}
.wa-float-pair .wa-pair-code-hint {
  font-size: 0.62rem;
  color: rgba(255, 255, 255, 0.35);
  margin: 0;
}
.wa-float-pair {
  /* action rows */
}
.wa-float-pair .wa-pair-action-row {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 9px;
  padding: 9px 11px;
}
.wa-float-pair .wa-pair-action-num {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  flex-shrink: 0;
  background: rgba(37, 211, 102, 0.2);
  border: 1px solid rgba(37, 211, 102, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  font-weight: 800;
  color: #86efac;
}
.wa-float-pair .wa-pair-action-body {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.wa-float-pair .wa-pair-action-title {
  font-size: 0.7rem;
  color: #e2e8f0;
  font-weight: 600;
  margin: 0;
}
.wa-float-pair .wa-pair-action-sub {
  font-size: 0.62rem;
  color: rgba(255, 255, 255, 0.3);
  margin: 0;
}
.wa-float-pair {
  /* WA open btn */
}
.wa-float-pair .wa-pair-wa-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  border-radius: 8px;
  background: #25D366;
  color: #000;
  font-size: 0.71rem;
  font-weight: 800;
  text-decoration: none;
  transition: opacity 0.15s;
  width: fit-content;
}
.wa-float-pair .wa-pair-wa-btn:hover {
  opacity: 0.87;
}
.wa-float-pair .wa-pair-wa-btn.secondary {
  background: rgba(37, 211, 102, 0.12);
  color: #86efac;
  border: 1px solid rgba(37, 211, 102, 0.3);
}
.wa-float-pair {
  /* divider */
}
.wa-float-pair .wa-pair-divider {
  display: flex;
  align-items: center;
  gap: 8px;
}
.wa-float-pair .wa-pair-divider::before, .wa-float-pair .wa-pair-divider::after {
  content: "";
  flex: 1;
  height: 1px;
  background: rgba(255, 255, 255, 0.08);
}
.wa-float-pair .wa-pair-divider span {
  font-size: 0.61rem;
  color: rgba(255, 255, 255, 0.28);
  white-space: nowrap;
}
.wa-float-pair {
  /* CTA */
}
.wa-float-pair .wa-pair-cta {
  width: 100%;
  padding: 9px;
  border-radius: 9px;
  border: none;
  background: linear-gradient(135deg, #25D366, #16a34a);
  color: #000;
  font-size: 0.78rem;
  font-weight: 800;
  cursor: pointer;
  transition: opacity 0.15s, transform 0.1s;
}
.wa-float-pair .wa-pair-cta:hover {
  opacity: 0.9;
  transform: translateY(-1px);
}
.wa-float-pair .wa-pair-cta:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.wa-float-pair .wa-pair-back {
  background: none;
  border: none;
  color: rgba(255, 255, 255, 0.28);
  font-size: 0.66rem;
  cursor: pointer;
  padding: 0;
  text-align: center;
}
.wa-float-pair .wa-pair-back:hover {
  color: rgba(255, 255, 255, 0.6);
}
.wa-float-pair {
  /* active badge */
}
.wa-float-pair .wa-pair-active-badge {
  display: flex;
  align-items: center;
  gap: 8px;
  background: rgba(37, 211, 102, 0.09);
  border: 1px solid rgba(37, 211, 102, 0.25);
  border-radius: 9px;
  padding: 8px 11px;
}
.wa-float-pair .wa-pair-active-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #22c55e;
  box-shadow: 0 0 7px #22c55e;
  flex-shrink: 0;
  animation: wa-dot-blink 1.4s ease-in-out infinite;
}
.wa-float-pair .wa-pair-active-title {
  font-size: 0.74rem;
  font-weight: 800;
  color: #86efac;
  margin: 0;
}
.wa-float-pair .wa-pair-active-phone {
  font-size: 0.62rem;
  color: rgba(255, 255, 255, 0.35);
  margin: 0;
}
.wa-float-pair .wa-pair-active-group {
  margin-left: auto;
  flex-shrink: 0;
}
.wa-float-pair {
  /* settings section */
}
.wa-float-pair .wa-pair-settings-section {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 9px;
  padding: 9px 11px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.wa-float-pair .wa-pair-settings-title {
  font-size: 0.69rem;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.45);
  margin: 0;
}
.wa-float-pair .wa-pair-settings-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.wa-float-pair .wa-pair-settings-row label {
  font-size: 0.67rem;
  color: rgba(255, 255, 255, 0.5);
  flex-shrink: 0;
}
.wa-float-pair .wa-pair-settings-row select {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 6px;
  padding: 4px 6px;
  color: #e2e8f0;
  font-size: 0.67rem;
  outline: none;
  cursor: pointer;
  max-width: 145px;
}
.wa-float-pair .wa-pair-settings-row select:focus {
  border-color: rgba(37, 211, 102, 0.45);
}
.wa-float-pair .wa-pair-settings-row select option {
  background: #1a2540;
}
.wa-float-pair .wa-pair-settings-row.toggle-row {
  align-items: flex-start;
}
.wa-float-pair .wa-pair-settings-sub {
  font-size: 0.6rem;
  color: rgba(255, 255, 255, 0.28);
  margin: 2px 0 0;
}
.wa-float-pair {
  /* toggle */
}
.wa-float-pair .wa-pair-toggle {
  background: none;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 6px;
  padding: 4px 12px;
  font-size: 0.7rem;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s;
  white-space: nowrap;
}
.wa-float-pair .wa-pair-toggle.on {
  background: rgba(37, 211, 102, 0.2);
  color: #22c55e;
  border-color: #22c55e;
}
.wa-float-pair .wa-pair-toggle.off {
  color: rgba(255, 255, 255, 0.4);
}
.wa-float-pair {
  /* share now */
}
.wa-float-pair .wa-pair-share-now {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  width: 100%;
  padding: 8px;
  border-radius: 9px;
  border: none;
  background: #25D366;
  color: #000;
  font-size: 0.74rem;
  font-weight: 800;
  cursor: pointer;
  transition: opacity 0.15s;
}
.wa-float-pair .wa-pair-share-now:hover {
  opacity: 0.88;
}
.wa-float-pair {
  /* disconnect */
}
.wa-float-pair .wa-pair-disconnect {
  flex: 1;
  padding: 7px;
  border-radius: 8px;
  border: 1px solid rgba(239, 68, 68, 0.22);
  background: rgba(239, 68, 68, 0.07);
  color: rgba(239, 68, 68, 0.65);
  font-size: 0.68rem;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s;
}
.wa-float-pair .wa-pair-disconnect:hover {
  background: rgba(239, 68, 68, 0.14);
  color: #ef4444;
}
.wa-float-pair {
  /* re-pair + disconnect row */
}
.wa-float-pair .wa-pair-action-btns-row {
  display: flex;
  gap: 6px;
}
.wa-float-pair .wa-pair-repair {
  flex: 1;
  padding: 7px;
  border-radius: 8px;
  border: 1px solid rgba(250, 204, 21, 0.28);
  background: rgba(250, 204, 21, 0.08);
  color: #facc15;
  font-size: 0.68rem;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s;
}
.wa-float-pair .wa-pair-repair:hover {
  background: rgba(250, 204, 21, 0.16);
}
.wa-float-pair {
  /* reconnect fallback (step 1) */
}
.wa-float-pair .wa-pair-reconnect {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  width: 100%;
  padding: 6px;
  border-radius: 8px;
  border: 1px dashed rgba(37, 211, 102, 0.3);
  background: transparent;
  color: rgba(134, 239, 172, 0.8);
  font-size: 0.65rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s;
}
.wa-float-pair .wa-pair-reconnect:hover {
  background: rgba(37, 211, 102, 0.08);
  color: #86efac;
}
.wa-float-pair {
  /* previous / next wizard nav */
}
.wa-float-pair .wa-pair-stepnav {
  display: flex;
  gap: 6px;
}
.wa-float-pair .wa-pair-stepnav__btn {
  flex: 1;
  padding: 7px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 0.68rem;
  font-weight: 700;
  transition: all 0.15s;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.04);
  color: rgba(255, 255, 255, 0.6);
}
.wa-float-pair .wa-pair-stepnav__btn:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.09);
  color: #fff;
}
.wa-float-pair .wa-pair-stepnav__btn:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}
.wa-float-pair .wa-pair-stepnav__btn.next {
  border-color: rgba(37, 211, 102, 0.3);
  background: rgba(37, 211, 102, 0.1);
  color: #86efac;
}
.wa-float-pair .wa-pair-stepnav__btn.next:hover:not(:disabled) {
  background: rgba(37, 211, 102, 0.18);
  color: #fff;
}
.wa-float-pair {
  /* fine print */
}
.wa-float-pair .wa-pair-fine {
  font-size: 0.61rem;
  color: rgba(255, 255, 255, 0.25);
  margin: 0;
  text-align: center;
}
.wa-float-pair .wa-pair-fine strong {
  color: rgba(255, 255, 255, 0.45);
