@keyframes aiDotPulse {
  0%, 100% {
    transform: scale(0.85);
    opacity: 0.7;
  }
  50% {
    transform: scale(1.2);
    opacity: 1;
  }
}
@keyframes aiPulse {
  0%, 100% {
    box-shadow: 0 0 20px rgba(76, 125, 255, 0.7);
  }
  50% {
    box-shadow: 0 0 40px rgb(76, 125, 255), 0 0 60px rgba(76, 125, 255, 0.4);
  }
}
@keyframes blink {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}
.ai-assistant__fire-pill {
  position: fixed;
  left: 7.5rem;
  top: 50%;
