/* Compact assistant settings sheet on phones.  Keep the whole dialog inside
   the viewport so the footer actions remain reachable above the run bar. */
@media (max-width: 600px) {
  .ai-assistant__overlay {
    align-items: flex-start;
    padding: 4.5rem 0.65rem 5.5rem;
    overflow-y: auto;
  }
  .ai-assistant__modal {
    width: 100%;
    max-width: 100%;
    max-height: calc(100dvh - 10rem);
    border-radius: 0.9rem;
  }
  .ai-assistant__modal-header {
    gap: 0.5rem;
    padding: 0.75rem 0.85rem;
  }
  .ai-assistant__modal-header h3 {
    font-size: 1rem;
  }
  .ai-assistant__close {
    width: 2.25rem;
    height: 2.25rem;
    font-size: 1rem;
  }
  .ai-assistant__body {
    padding: 0.85rem;
    gap: 0.75rem;
  }
  .ai-assistant__field label {
    font-size: 0.72rem;
    margin-bottom: 0.3rem;
  }
  .ai-assistant__field input, .ai-assistant__field select {
    padding: 0.55rem 0.65rem;
    font-size: 0.9rem;
    border-radius: 0.5rem;
  }
  .ai-assistant__field--toggle {
    padding: 0.7rem;
    border-radius: 0.65rem;
  }
  .ai-assistant__field--toggle p {
    font-size: 0.75rem;
  }
  .ai-assistant__field-row {
    gap: 0.5rem;
  }
  .ai-assistant__trade-types {
    gap: 0.4rem;
  }
  .ai-assistant__type-btn {
    padding: 0.55rem 0.35rem;
    font-size: 0.8rem;
    border-radius: 0.5rem;
  }
  .ai-assistant__load-run {
    margin-top: 0.5rem;
    padding: 0.7rem;
    font-size: 0.95rem;
    border-radius: 0.55rem;
  }
  .ai-assistant__footer {
    gap: 0.5rem;
    padding: 0.7rem 0.85rem;
  }
  .ai-assistant__btn {
    padding: 0.65rem 0.8rem;
    font-size: 0.85rem;
    border-radius: 0.55rem;
  }
  .ai-assistant__signal {
    padding: 0.75rem;
    border-radius: 0.7rem;
  }
  .ai-assistant__signal-market {
    font-size: 1rem;
    margin-top: 0.4rem;
  }
  .ai-assistant__signal-type {
    font-size: 0.85rem;
  }
}
/* ─── Install Popup ─────────────────────────────────────────────
   Centered bottom-of-screen card that appears on every load.
   Clean dark design matching the app's brand palette.
   ─────────────────────────────────────────────────────────────── */
.install-popup {
  position: fixed;
  bottom: 2rem;
  left: 50%;
  transform: translateX(-50%);
  z-index: 99999;
  width: min(42rem, 100vw - 2.4rem);
  animation: install-popup-in 0.38s cubic-bezier(0.16, 1, 0.3, 1) both;
}
@media (max-width: 480px) {
  .install-popup {
    bottom: 1.2rem;
    width: calc(100vw - 2rem);
  }
}
.install-popup__card {
  position: relative;
  background: linear-gradient(145deg, #0d1b2a 0%, #0a1520 60%, #071018 100%);
  border: 1px solid rgba(0, 200, 83, 0.3);
  border-radius: 1.8rem;
  padding: 2rem 2rem 1.6rem;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.6), 0 0 0 1px rgba(0, 255, 100, 0.08) inset, 0 4px 24px rgba(0, 200, 83, 0.15);
  display: flex;
  flex-direction: column;
  gap: 1.4rem;
}
@media (max-width: 480px) {
  .install-popup__card {
    padding: 1.6rem 1.4rem 1.2rem;
    border-radius: 1.4rem;
    gap: 1.2rem;
  }
}
.install-popup {
  /* ── Close button ─────────────────────────────────────── */
}
.install-popup__close {
  position: absolute;
  top: 1.2rem;
  right: 1.2rem;
  width: 28px;
  height: 28px;
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.06);
  color: rgba(255, 255, 255, 0.5);
  font-size: 1.2rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.15s;
}
.install-popup__close:hover {
  background: rgba(255, 255, 255, 0.12);
  color: #fff;
  border-color: rgba(255, 255, 255, 0.3);
}
.install-popup {
  /* ── Top row: icon + brand ────────────────────────────── */
}
.install-popup__top {
  display: flex;
  align-items: center;
  gap: 1.4rem;
  padding-right: 2.4rem; /* make room for close btn */
}
.install-popup__icon {
  flex-shrink: 0;
  width: 5.6rem;
  height: 5.6rem;
  border-radius: 1.2rem;
  overflow: hidden;
  border: 1.5px solid rgba(0, 200, 83, 0.4);
  box-shadow: 0 0 16px rgba(0, 200, 83, 0.2);
}
.install-popup__icon img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
@media (max-width: 480px) {
  .install-popup__icon {
    width: 4.8rem;
    height: 4.8rem;
  }
}
.install-popup__brand {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}
.install-popup__title {
  font-size: 1.8rem;
  font-weight: 800;
  color: #fff;
  letter-spacing: -0.02em;
  line-height: 1.2;
}
@media (max-width: 480px) {
  .install-popup__title {
    font-size: 1.6rem;
  }
}
.install-popup__sub {
  font-size: 1.15rem;
  color: rgba(255, 255, 255, 0.45);
  font-weight: 500;
}
.install-popup {
  /* ── Feature list ─────────────────────────────────────── */
}
.install-popup__features {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
}
.install-popup__features li {
  font-size: 1.25rem;
  color: rgba(255, 255, 255, 0.72);
  display: flex;
  align-items: center;
  gap: 0.6rem;
  line-height: 1.4;
}
@media (max-width: 480px) {
  .install-popup__features {
    gap: 0.5rem;
  }
  .install-popup__features li {
    font-size: 1.15rem;
  }
}
.install-popup {
  /* ── Primary install button ───────────────────────────── */
}
.install-popup__btn {
  width: 100%;
  padding: 1.3rem;
  border: none;
  border-radius: 1.2rem;
  font-size: 1.5rem;
  font-weight: 800;
  cursor: pointer;
  font-family: inherit;
  transition: all 0.2s;
  letter-spacing: 0.02em;
}
.install-popup__btn--primary {
  background: linear-gradient(135deg, #00c853, #007a35);
  color: #fff;
  box-shadow: 0 4px 20px rgba(0, 200, 83, 0.35);
}
.install-popup__btn--primary:hover {
  filter: brightness(1.08);
  transform: translateY(-1px);
  box-shadow: 0 6px 24px rgba(0, 200, 83, 0.45);
}
.install-popup__btn--primary:active {
  transform: translateY(0);
}
@media (max-width: 480px) {
  .install-popup__btn {
    padding: 1.1rem;
    font-size: 1.35rem;
  }
}
.install-popup {
  /* ── iOS instructions ─────────────────────────────────── */
}
.install-popup__ios {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 1rem;
  padding: 1.2rem 1.4rem;
}
.install-popup__ios-title {
  font-size: 1.3rem;
  font-weight: 700;
  color: #00c853;
  margin: 0 0 0.8rem;
}
.install-popup__ios-steps {
  margin: 0;
  padding-inline-start: 1.8rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.install-popup__ios-steps li {
  font-size: 1.2rem;
  color: rgba(255, 255, 255, 0.7);
  line-height: 1.5;
}
.install-popup__ios-icon {
  display: inline-block;
  padding: 1px 6px;
  background: rgba(0, 122, 255, 0.2);
  border-radius: 4px;
  color: #4fc3f7;
  font-size: 1.1rem;
  font-weight: 700;
  margin: 0 2px;
}
.install-popup {
  /* ── Desktop manual fallback ──────────────────────────── */
}
.install-popup__manual {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 1rem;
  padding: 1.2rem 1.4rem;
}
.install-popup__manual p {
  font-size: 1.2rem;
  color: rgba(255, 255, 255, 0.65);
  margin: 0;
  line-height: 1.6;
}
.install-popup__manual p strong {
  color: #fff;
}
.install-popup__manual p span {
  font-size: 1.4rem;
  color: #00c853;
}
.install-popup {
  /* ── "Maybe later" dismiss link ───────────────────────── */
}
.install-popup__later {
  background: none;
  border: none;
  color: rgba(255, 255, 255, 0.3);
  font-size: 1.2rem;
  cursor: pointer;
  font-family: inherit;
  text-align: center;
  padding: 0.2rem;
  transition: color 0.15s;
}
.install-popup__later:hover {
  color: rgba(255, 255, 255, 0.6);
}

/* ── Entry animation ────────────────────────────────────── */
@keyframes install-popup-in {
  from {
    opacity: 0;
    transform: translateX(-50%) translateY(2.4rem) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translateX(-50%) translateY(0) scale(1);
  }
}.risk-disclaimer {
  position: fixed;
  z-index: 9998;
  width: 260px;
  border-radius: 12px;
  background: rgba(10, 2, 2, 0.95);
  border: 1.5px solid rgba(234, 179, 8, 0.4);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.6), 0 0 20px rgba(234, 179, 8, 0.08);
  backdrop-filter: blur(10px);
  font-size: 12px;
  user-select: none;
}
.risk-disclaimer__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  background: rgba(15, 8, 0, 0.8);
  border-radius: 10px 10px 0 0;
  border-bottom: 1px solid rgba(234, 179, 8, 0.15);
  cursor: grab;
}
.risk-disclaimer__header:active {
  cursor: grabbing;
}
.risk-disclaimer__title {
  font-size: 12px;
  font-weight: 700;
  color: #eab308;
}
.risk-disclaimer__min-btn {
  width: 22px;
  height: 22px;
  border-radius: 4px;
  border: 1px solid rgba(234, 179, 8, 0.2);
  background: transparent;
  color: #ca8a04;
  font-size: 10px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}
.risk-disclaimer__min-btn:hover {
  background: rgba(234, 179, 8, 0.15);
}
.risk-disclaimer__body {
  padding: 12px 14px;
}
.risk-disclaimer__body p {
  font-size: 11px;
  color: #d1a832;
  line-height: 1.6;
  margin: 0 0 8px;
}
.risk-disclaimer__body p:last-of-type {
  margin-bottom: 12px;
}
.risk-disclaimer__body strong {
  color: #fbbf24;
}
.risk-disclaimer__legal {
  font-size: 10px;
  color: rgba(209, 168, 50, 0.6);
  font-style: italic;
}
.risk-disclaimer__accept-btn {
  width: 100%;
  padding: 9px;
  border-radius: 8px;
  background: linear-gradient(135deg, #ca8a04, #eab308);
  color: #000;
  border: none;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s;
}
.risk-disclaimer__accept-btn:hover {
  filter: brightness(1.1);
}
/**
 * Global Responsive Overrides
 * Covers: 360px (Nokia C32) · 480px · 600px · 768px · 920px · 1024px · 1280px · 1440px+
 * Applied on top of all component/page styles.
 */
/* ─── Root — prevent horizontal scroll on every viewport ─── */
html, body, #root {
  overflow-x: hidden;
  -webkit-text-size-adjust: 100%;
  max-width: 100vw;
}

/* ═══════════════════════════════════════════════════
   FLOATING RUN BUTTON
   ═══════════════════════════════════════════════════ */
/* Keep floating run button inside safe area on ALL screens */
.floating-run-btn {
  max-width: calc(100vw - 8px);
  /* Clamp vertically so it never goes under the header or off-screen bottom */
  max-height: calc(100vh - 120px);
}

@media (max-width: 600px) {
  .floating-run-btn {
    /* On mobile: keep from going under nav, scale down slightly */
    max-width: calc(100vw - 12px);
    transform-origin: left center;
  }
  /* Ensure floating WhatsApp button doesn't collide */
  .whatsapp-float {
    right: 10px !important;
  }
}
/* ═══════════════════════════════════════════════════
   HEADER / NAV
   ═══════════════════════════════════════════════════ */
@media (max-width: 768px) {
  .deriv-header {
    padding: 0 0.8rem !important;
    height: auto !important;
    min-height: 4.8rem;
  }
}
@media (max-width: 600px) {
  .deriv-header {
    padding: 0 0.6rem !important;
    min-height: 4.4rem;
  }
  .header__deposit-btn {
    padding: 4px 8px !important;
    font-size: 1rem !important;
  }
  .header__deposit-btn span:last-child {
    display: none;
  }
  .deriv-account-switcher__button {
    margin-inline-end: 0 !important;
  }
}
