  }
  .mtp-buy-btn {
    padding: 0.75rem 0.3rem !important;
  }
  .mtp-buy-btn__label {
    font-size: 0.82rem !important;
  }
  .mtp-buy-btn__pct {
    font-size: 0.82rem !important;
  }
  .mt-circle {
    width: 34px !important;
    height: 34px !important;
  }
}
