  .main {
    overflow-x: hidden;
  }
  /* Bot builder workspace */
  .bot {
    --bot-content-width: calc(100vw - 300px) !important;
  }
  /* Dashboard panels don't overflow */
  .bot-dashboard {
    overflow-x: hidden;
  }
}
